module parity_8bit (
    input [7:0] in,
    output out
);

    wire w1, w2, w3, w4;

    assign w1 = ~in[1] & in[0];
    assign w2 = ~(in[3] & in[2]);
    assign w3 = w1 | w2;

    assign w4 = ~(in[5] & in[4]);
    assign w3 = w3 | w4;

    assign w3 = w3 | ~in[7] & in[6];

    assign out = w3;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    reg [3:0] out;
    wire [3:0] m_0;
    wire [3:0] m_1;
    wire [3:0] m_2;
    wire [3:0] m_3;
    assign m_0 = (sign_extend(sel[0])) ? (sel[1] ? (31'h1) : (31'h0)) : (31'h0);
    assign m_1 = (sign_extend(sel[0])) ? ((~sel[1]) ? (~sel[1]) : (sel[1])) : (~sel[1] & ~sel[0]);
    assign m_2 = (sign_extend(sel[1])) ? (sel[1] ? (sel[0]) : (~sel[0])) : (31'h0);
    assign m_3 = (sign_extend(sel[1])) ? ((~sel[1]) ? (1) : (0)) : (~sel[1] & ~sel[0]);
    assign out = {{9{out}}, m_0 + {1{m_1+m_2}}} ? (31'h0) : ({~m_0[3:0], m_1+m_2[3:0]}) ? (~in) : (
        in
    );
endmodule

module majority (
    input a, b, c,
    output out
);
    and U1 (.Y(out), .A(c & (b | a)));
    or U2 (.Y(out), .A(c & (b | a)));
    and U3 (.Y(A), .A(c & b));
    and U4 (.Y(B), .A(b & a));
    or U5 (.Y(C), .A(A, a));
    or U6 (.Y(out), .A(B, C));
endmodule

