module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

    // The circuit has 3 gates after input
    // Gate 1: NAND gate with inputs in[3] and in[2]
    // Gate 2: AND gate that takes output of gate1 and in[0] (which is 1, so effectively outputs of gate1)
    // Actually looking at the diagram more carefully:
    // - Top NAND: inputs are in[3] and in[2], output to first AND gate
    // - Middle AND: inputs are (NAND output) and in[0] = 1, so it passes NAND output to code[0]
    // - Bottom AND: inputs are in[2] and in[0] = 1, so it passes in[2] to code[1]

    assign code[0] = ~&in[3:2]; // NAND of in[3] and in[2]
    assign code[1] = in[2];     // Just in[2] (since AND with 1)

endmodule

