module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

    reg [7:0] count;

    // Infer flip-flops from feedback loops
    reg [7:0] q_reg;

    always @(posedge clk) begin
        case (rst)
            1'b0: begin
                q_reg[0] <= q_reg[0]; // Placeholder for S_SDFF_PP0_ Q output from first flip-flop
                q_reg[1] <= q_reg[1];
                q_reg[2] <= q_reg[2];
                q_reg[3] <= q_reg[3];
                q_reg[4] <= q_reg[4];
                q_reg[5] <= q_reg[5];
                q_reg[6] <= q_reg[6];
                q_reg[7] <= q_reg[7];
            end
            1'b1: begin
                q_reg[0] <= q_reg[0] | q_reg[1]; // OR gate logic from schematic
                q_reg[1] <= q_reg[1] ^ q_reg[2]; // XOR gate logic
                q_reg[2] <= q_reg[2] & q_reg[6]; // AND gate logic
                q_reg[3] <= q_reg[3] | q_reg[4];
                q_reg[4] <= q_reg[4] ^ q_reg[5];
                q_reg[5] <= q_reg[5] & q_reg[6];
                q_reg[6] <= q_reg[6] | q_reg[7];
                q_reg[7] <= q_reg[7] ^ q_reg[0];
            end
            default: begin
                q_reg <= q_reg; // Reset to previous state for invalid rst
            end
        endcase
    end

    assign count = q_reg; // Assign final result to output

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);
    wire [3:0] val_1_wire;

    assign q[0] = clk & ~rst;
    assign q[1] = (~clk) & rst;
    assign q[2] = (clk & rst);
    assign val_1_wire = q[3:0];

    (* synthesis *)
    always @(posedge val_1_wire) begin
        q[0] = q[3];
        q[1] = q[2];
        q[2] = q[1];
        q[3] = q[0];
    end

endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);

    wire c_clk;
    wire q_reg_0;
    wire q_reg_1;
    wire q_reg_2;
    wire q_reg_3;
    wire q_reg_4;
    wire q_reg_5;
    wire q_reg_6;
    wire q_reg_7;
    wire q_reg_8;

    assign c_clk = clk;
    assign q_reg_0 = rst;
    assign q_reg_1 = load;
    assign q_reg_2 = pin[0];
    assign q_reg_3 = pin[1];
    assign q_reg_4 = pin[2];
    assign q_reg_5 = pin[3];
    assign q_reg_6 = pin[4];
    assign q_reg_7 = pin[5];
    assign q_reg_8 = pin[6];

    always @(posedge c_clk or negedge q_reg_0) begin
        if (!q_reg_0) begin
            q_reg_1 <= q_reg_0;
        end else begin
            q_reg_1 <= q_reg_0;
            q_reg_2 <= q_reg_1;
            q_reg_3 <= q_reg_2;
            q_reg_4 <= q_reg_3;
            q_reg_5 <= q_reg_4;
            q_reg_6 <= q_reg_5;
            q_reg_7 <= q_reg_6;
            q_reg_8 <= q_reg_7;
        end
    end

    assign sout = q_reg_8;

endmodule

module priority_encoder_4to2 (
    input  [3:0] in,
    output reg   [1:0] out,
    output        valid
);
    always @(*) begin
        out = 2'b00;
        valid = 1'b0;

        if (in[3]) begin
            out[1] = !(in[3] | in[2]);
            out[0] = in[3] & in[2];
            valid = in[3] & in[0];
        end else if (in[2]) begin
            out[1] = 1'b1;
            out[0] = 1'b0;
            valid = in[2] & in[0];
        end else if (in[0]) begin
            out[1] = 1'b0;
            out[0] = 1'b1;
            valid = in[0];
        end
    end
