module siso_8bit(
    input clk,
    input rst,
    input sin,
    output reg sout
);

    reg [2:0] count;
    reg internal_val_3;

    always @(*) begin
        if (rst) begin
            count <= 0;
        end else begin
            count = {1'b0, count[1:0]};
        end
        case (count[1:0])
            2'b00: internal_val_3 = count[2];
            2'b01: internal_val_3 = (count[2] | sin);
            2'b10: internal_val_3 = ((count[2] & sin) & !rst);
            2'b11: internal_val_3 = ((count[2] | sin) & !rst);
            default: internal_val_3 = sout;
        endcase

        sout = (count == 3'b000) ? internal_val_3 : clk;
    end

    always @(posedge rst) begin
        if (sin) begin
            sout <= clk;
        end else begin
            sout <= internal_val_3;
        end
    end

    always @(posedge rst) begin
        if (sin) begin
            count <= 3'b000;
        end else begin
            count <= count + 1;
        end
    end

endmodule

