    for (integer i = 7; i >= 0; i = i - 1)
      $display("state[%d] = %b, input_val_1 = %b", i, state[0], d[i]);
  end

  // Replicate the behavior shown in the diagram
  for (integer i = 0; i < 8; i = i + 1) begin
      if (state[0] == 1'b1) 
        state[i] <= d[i];
      else 
        state[i] <= state[0];

      if (state[i] == 1'b1 && d[0] == 1'b1) begin
        q <= {i, 7'b0};
        // This matches the pattern of q outputting a bit shifted version based on which DFF is 1
      end
      else 
        q <= {state[0], 7'b0}; // When all are 0, this defaults to 0
  end

  // Reset logic: assume simultaneous reset on all bits when d is 0 and state[0] is 1 (from diagram)
  if (d == 8'h0 && state[0] == 1'b1) begin
      state <= 8'h0;
      q <= 8'h00;
  end

endmodule

