      4'b0010: q_next = ((rst_n | clk) & valid_count) | ((~rst_n) & valid_count);
      4'b0011: q_next = ((rst_n | clk) & valid_count) | ((~rst_n) & valid_count);
      default: q_next = d_q;
    endcase
  end

  // Assign output
  assign out = q;

endmodule

