module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

always @(posedge data_en) begin
    case (data_in)
        4'd0: begin
            case (arstn)
                1'd0: dataout <= {clk_a, {3{arstn}}};
                1'd1: dataout <= {clk_a, clk_b, {3{arstn}}};
                default: dataout <= {clk_a, {3{arstn}}};
            endcase
        end
        4'd1: begin
            case (arstn)
                1'd0: dataout <= {clk_a, clk_b, brstn, {1{arstn}}};
                1'd1: dataout <= {clk_a, {3{arstn}}};
                default: dataout <= {clk_a, clk_b, brstn, {1{arstn}}};
            endcase
        end
        4'd2: begin
            case (arstn)
                1'd0: dataout <= {clk_a, brstn, {2{arstn}}};
                1'd1: dataout <= {clk_a, clk_b, {2{arstn}}};
                default: dataout <= {clk_a, brstn, {2{arstn}}};
            endcase
        end
        4'd3: begin
            case (arstn)
                1'd0: dataout <= {clk_a, {1{arstn}}, brstn, clk_b};
