                default: dataout <= {clk_a, {1{arstn}}, brstn, clk_b};
            endcase
        end
        default: begin
            case (arstn)
                1'd0: dataout <= {clk_a, {3{arstn}}};
                1'd1: dataout <= {clk_a, {3{arstn}}};
                default: dataout <= {clk_a, {3{arstn}}};
            endcase
        end
