module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

  // Internal signals for flip-flops
  reg Q1, Q2;
  // Intermediate signals for combinational logic
  wire S_AND1, S_AND2, S_AND3, S_AND4, S_AND5, S_AND6;
  wire S_NAND1, S_NAND2, S_NAND3;

  // Assignments for NAND gates
  assign S_NAND1 = ~((clk & Q1) | (clk & ~Q2));
  assign S_NAND2 = ~((clk & Q2) | (rst_n & ~Q1));
  assign S_NAND3 = ~((data_in & Q1) | (sequence_detected & ~Q2));

  // Assignments for AND gates
  assign S_AND1 = (clk & Q1) | (clk & ~Q2);
  assign S_AND2 = (clk & Q2) | (rst_n & ~Q1);
  assign S_AND3 = (data_in & Q1) | (sequence_detected & ~Q2);
  assign S_AND4 = (data_in & Q2) | (sequence_detected & ~Q1);
  assign S_AND5 = (clk & Q2) | (data_in & ~Q1);
  assign S_AND6 = (rst_n & Q1) | (data_in & ~Q2);

  // Continuous assignments for D flip-flops
  assign sequence_detected = Q1;
  assign Q2 = S_AND1;

endmodule
